using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps;using MapSharedProps.EditorTools;
// Dedicated background Editor test; no Player build or scene save.
public static class ChestClusterLightChecks {
 [Serializable]class Report{public bool pass;public string error;public int prefabs,lightsPerGold,activeLightsWithSixChests,otherChestLights,legacySlots,extendedSlots;public bool collidersShared,standardLit,rubyPreserved,disabledLightsOff;}
 static void Check(bool v,string label){if(!v)throw new Exception(label);}
 static string Arg(string key){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,key);if(i<0||i+1>=a.Length)throw new Exception("Missing "+key);return a[i+1];}
 public static void Run(){var report=new Report();int code=0;string output=Arg("-props-output");Directory.CreateDirectory(output);try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);string input=Arg("-props-export");var data=SmallPropsV1.Read(Path.Combine(input,"small_props.json"));report.legacySlots=data.chestEffectsV1.Single(x=>x.id=="treasurechest_gold").slots.Length;report.extendedSlots=data.chestEffectsV2.Single(x=>x.id=="treasurechest_gold").slots.Length;Check(report.legacySlots==6&&report.extendedSlots==18,"Frozen V1 and bounded V2");
  string folder=AssetDatabase.GenerateUniqueAssetPath("Assets/ChestClusterLightProof");AssetDatabase.CreateFolder("Assets",Path.GetFileName(folder));var prefabs=new Dictionary<string,GameObject>();SmallPropsV1.Build(input,folder,new GameObject("Review placement").transform,Shader.Find("MapSharedProps/Lit"),prefabs);report.prefabs=prefabs.Count;Check(report.prefabs==43,"43 prefabs");var gold=prefabs["treasurechest_gold"];
  report.lightsPerGold=gold.GetComponentsInChildren<Light>().Length;report.otherChestLights=prefabs.Where(x=>x.Key.StartsWith("treasurechest")&&x.Key!="treasurechest_gold").Sum(x=>x.Value.GetComponentsInChildren<Light>().Length);Check(report.lightsPerGold==2&&report.otherChestLights==0,"Only gold owns two lights");Check(gold.GetComponentsInChildren<Light>().All(x=>x.type==LightType.Point&&x.shadows==LightShadows.None),"Unshadowed point clusters");
  var materials=gold.GetComponent<Renderer>().sharedMaterials;report.standardLit=materials.Any(x=>x.shader.name=="Universal Render Pipeline/Lit"&&x.GetFloat("_Metallic")==.8f&&x.GetFloat("_Smoothness")==.8f);report.rubyPreserved=materials.Any(x=>x.shader.name=="MapSharedProps/ChestMetal");Check(report.standardLit&&report.rubyPreserved,"Standard gold and separate ruby retained");
  var camera=new GameObject("Budget camera").AddComponent<Camera>();camera.tag="MainCamera";camera.transform.position=new Vector3(0,3,-5);var copies=new List<GameObject>();for(int k=0;k<6;k++){var o=(GameObject)PrefabUtility.InstantiatePrefab(gold);o.transform.position=new Vector3(k*.3f,0,0);o.GetComponent<ChestPresentation>().SetTime(.8f);copies.Add(o);}ChestPresentation.RefreshLights(camera);report.activeLightsWithSixChests=copies.Sum(x=>x.GetComponentsInChildren<Light>().Count(l=>l.enabled));report.collidersShared=copies.All(x=>x.GetComponent<MeshCollider>().sharedMesh==gold.GetComponent<MeshCollider>().sharedMesh);Check(report.activeLightsWithSixChests==8&&report.collidersShared,"Eight-light cap and shared collider");foreach(var o in copies){o.GetComponent<ChestPresentation>().SetLightVisibility(false);o.SetActive(false);}report.disabledLightsOff=copies.All(x=>x.GetComponentsInChildren<Light>(true).All(l=>!l.enabled));Check(report.disabledLightsOff,"Disabled objects leave no lights");
  Check(!ShaderUtil.ShaderHasError(Shader.Find("MapSharedProps/ChestFx")),"FX shader compiled");AssetDatabase.SaveAssets();report.pass=true;
 }catch(Exception e){report.error=e.ToString();Debug.LogException(e);code=1;}finally{File.WriteAllText(Path.Combine(output,"editor-light-checks.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(code);}}
}
